          JAVA: `class Solution {
    public int[] nearestStations(int[][] points, int k) {
        Integer[] order = new Integer[points.length];
        for (int i = 0; i < order.length; i++) order[i] = i;
        Arrays.sort(order, (a, b) -> {
            int da = points[a][0] * points[a][0] + points[a][1] * points[a][1];
            int db = points[b][0] * points[b][0] + points[b][1] * points[b][1];
            return da != db ? Integer.compare(da, db) : Integer.compare(a, b);
        });
        int[] result = new int[k];
        for (int i = 0; i < k; i++) result[i] = order[i];
        return result;
    }
}`,
