          PYTHON: `def minSpliceCost(lengths: List[int]) -> int:
    pool = list(lengths)
    cost = 0
    while len(pool) > 1:
        pool.sort()
        joined = pool[0] + pool[1]
        cost += joined
        pool = pool[2:] + [joined]
    return cost`,
          JAVA: `class Solution {
    public int minSpliceCost(int[] lengths) {
        List<Integer> pool = new ArrayList<>();
        for (int len : lengths) pool.add(len);
        int cost = 0;
        while (pool.size() > 1) {
            Collections.sort(pool);
            int joined = pool.remove(0) + pool.remove(0);
            cost += joined;
            pool.add(joined);
        }
        return cost;
    }
}`,
