          JAVA: `class Solution {
    public int kthSmallestInGrid(int[][] grid, int k) {
        // Entries are {value, row, column}.
        PriorityQueue<int[]> heap = new PriorityQueue<>((a, b) -> Integer.compare(a[0], b[0]));
        for (int r = 0; r < grid.length; r++) heap.offer(new int[] { grid[r][0], r, 0 });

        for (int i = 0; i < k - 1; i++) {
            int[] top = heap.poll();
            int r = top[1], c = top[2] + 1;
            if (c < grid[r].length) heap.offer(new int[] { grid[r][c], r, c });
        }

        return heap.peek()[0];
    }
}`,
